<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { AlertTriangle, CarFront, Search, VideoOff } from 'lucide-vue-next';
import { api } from '../api';
import { useSessionStore } from '../stores/session';
import { label, number, params, stamp, useMonitoringOptions, type PageResult } from '../province-monitoring';
import QueryPanel from '../components/QueryPanel.vue';
import QueryField from '../components/QueryField.vue';
import ProvinceMonitoringMap from '../components/ProvinceMonitoringMap.vue';
import ProvincePageState from '../components/ProvincePageState.vue';
import AccidentVideoPlayer from '../components/AccidentVideoPlayer.vue';
import EvidenceTimeline from '../components/EvidenceTimeline.vue';
import '../province-monitoring.css';
const route = useRoute(), router = useRouter(), session = useSessionStore(), { options, loadOptions } = useMonitoringOptions();
const q = ref(''), workspaceId = ref(''), status = ref(''), dateRange = ref<[string, string] | null>(null), videoState = ref(''), page = ref(1), rows = ref<any[]>([]), total = ref(0), loading = ref(false), error = ref(''), detailLoading = ref(false), detailError = ref(''), detail = ref<any>(), selectedId = ref(''), windowMinutes = ref(5), cursor = ref(0), playing = ref(false), speed = ref(1);
let listGeneration = 0, detailGeneration = 0, navigationGeneration = 0, listKey = '', listController: AbortController | undefined, detailController: AbortController | undefined;
const windowFrom = computed(() => Date.parse(detail.value?.window.from) || 0), windowTo = computed(() => Date.parse(detail.value?.window.to) || 0), incidentAt = computed(() => Date.parse(detail.value?.occurredAt) || 0);
const events = computed<any[]>(() => !detail.value ? [] : [...detail.value.alerts.map((row: any) => ({ ...row, kind: '告警' })), ...detail.value.violations.map((row: any) => ({ ...row, kind: '违规' })), { id: detail.value.id, occurredAt: detail.value.occurredAt, title: detail.value.title, kind: '事故' }].sort((a, b) => Date.parse(a.occurredAt) - Date.parse(b.occurredAt)));
const currentFix = computed(() => { const points = detail.value?.track ?? []; if (!points.length) return null; const closest = points.reduce((best: any, row: any) => Math.abs(Date.parse(row.recordedAt) - cursor.value) < Math.abs(Date.parse(best.recordedAt) - cursor.value) ? row : best); return Math.abs(Date.parse(closest.recordedAt) - cursor.value) <= 60000 ? closest : null; });
const canWrite = computed(() => session.user?.permissions.includes('system:organization:update'));
function values() { return { q: q.value.trim(), workspaceId: workspaceId.value, status: status.value, from: dateRange.value?.[0], to: dateRange.value?.[1], videoState: videoState.value, vehicleId: typeof route.query.vehicleId === 'string' ? route.query.vehicleId : undefined, page: page.value, pageSize: 5 }; }
async function loadList() {
  const current = ++listGeneration; listController?.abort(); listController = new AbortController(); loading.value = true; error.value = '';
  try { if (!options.value.workspaces.length) await loadOptions(); const result = await api<PageResult>(`/province/accidents?${params(values())}`, { signal: listController.signal }); if (current !== listGeneration) return; rows.value = result.items; total.value = result.total; }
  catch (reason) { if (current === listGeneration && !listController.signal.aborted) error.value = reason instanceof Error ? reason.message : '事故列表读取失败'; }
  finally { if (current === listGeneration) loading.value = false; }
}
async function loadDetail() {
  const current = ++detailGeneration; detailController?.abort(); detailController = new AbortController(); playing.value = false; detailError.value = ''; detail.value = undefined;
  if (!selectedId.value) { detailLoading.value = false; return; } detailLoading.value = true;
  try { const result = await api<any>(`/province/accidents/${selectedId.value}?${params({ workspaceId: workspaceId.value, vehicleId: route.query.vehicleId, windowMinutes: windowMinutes.value })}`, { signal: detailController.signal }); if (current !== detailGeneration) return; detail.value = result; cursor.value = Date.parse(result.occurredAt); }
  catch (reason) { if (current === detailGeneration && !detailController.signal.aborted) detailError.value = reason instanceof Error ? reason.message : '事故详情读取失败'; }
  finally { if (current === detailGeneration) detailLoading.value = false; }
}
function search(reset = true) { if (reset) page.value = 1; const query = Object.fromEntries(params({ ...values(), pageSize: undefined })); const fullPath = router.resolve({ path: '/province/accidents', query }).fullPath; if (route.fullPath === fullPath) void loadList().then(() => { selectedId.value = rows.value[0]?.id ?? ''; void loadDetail(); }); else void router.replace({ path: '/province/accidents', query }); }
function choose(id: string) { void router.replace({ path: route.path, query: { ...route.query, accidentId: id } }); }
function reset() { q.value = workspaceId.value = status.value = videoState.value = ''; dateRange.value = null; const { vehicleId: _vehicle, ...query } = route.query; void router.replace({ path: route.path, query: { ...query, q: undefined, workspaceId: undefined, status: undefined, videoState: undefined, from: undefined, to: undefined, accidentId: undefined, page: '1' } }); }
function openVehicle() { if (!detail.value) return; void router.push({ path: '/province/vehicles', query: { vehicleId: detail.value.vehicleId, workspaceId: detail.value.workspaceId, tab: 'accidents' } }); }
function supervise() { if (!detail.value) return; const item = detail.value; void router.push({ path: '/province/coordination', query: { kind: 'SUPERVISION', relatedType: 'ACCIDENT', relatedId: item.id, create: '1', title: `${item.title}核查督办`, basis: item.businessNo, workspaceId: item.workspaceId, level: item.level, description: `请核查${item.vehicle.businessNo}于${stamp(item.occurredAt)}发生的${item.title}，补充事故前后轨迹、视频及属地处置资料。` } }); }
watch(() => route.query, async query => {
  const nav = ++navigationGeneration; q.value = String(query.q ?? ''); workspaceId.value = String(query.workspaceId ?? ''); status.value = String(query.status ?? ''); videoState.value = String(query.videoState ?? ''); dateRange.value = query.from && query.to ? [String(query.from), String(query.to)] : null; page.value = Math.max(1, Number(query.page) || 1);
  const key = String(params(values())); if (key !== listKey) { listKey = key; await loadList(); } if (nav !== navigationGeneration) return; selectedId.value = typeof query.accidentId === 'string' ? query.accidentId : rows.value[0]?.id ?? ''; void loadDetail();
}, { immediate: true });
onBeforeUnmount(() => { listGeneration++; detailGeneration++; navigationGeneration++; listController?.abort(); detailController?.abort(); playing.value = false; });
</script>
<template><section class="pm-page"><h1 class="sr-only">事故回溯</h1><QueryPanel :loading="loading" @search="search()" @reset="reset"><QueryField label="事故编号 / 车辆" keyword><el-input v-model="q" aria-label="事故编号 / 车辆" :prefix-icon="Search" clearable placeholder="事故编号、标题或车辆编号"/></QueryField><QueryField label="所属地市"><el-select v-model="workspaceId" aria-label="所属地市" clearable placeholder="全部地市" @change="search()"><el-option v-for="city in options.workspaces" :key="city.id" :value="city.id" :label="city.cityName"/></el-select></QueryField><QueryField label="发生时间" wide><el-date-picker v-model="dateRange" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" aria-label="事故发生时间范围"/></QueryField><QueryField label="处置状态"><el-select v-model="status" aria-label="处置状态" clearable placeholder="全部状态"><el-option v-for="state in ['REPORTED','ACCEPTED','INVESTIGATING','RESPONSIBILITY_DETERMINED','PROCESSING','CLOSED','ARCHIVED']" :key="state" :label="label(state)" :value="state"/></el-select></QueryField><QueryField label="视频资料"><el-select v-model="videoState" aria-label="视频资料" clearable placeholder="全部视频状态"><el-option label="有可用录像" value="AVAILABLE"/><el-option label="暂无可用录像" value="MISSING"/></el-select></QueryField></QueryPanel>
<ProvincePageState :error="error" :loading="loading" @retry="loadList"><div class="pm-accident-workspace"><aside class="pm-case-list" aria-label="事故记录"><header><strong>事故记录</strong><span>共 {{ total }} 起</span></header><button v-for="row in rows" :key="row.id" type="button" :aria-pressed="selectedId === row.id" @click="choose(row.id)"><div><strong>{{ row.title }}</strong><el-tag size="small" effect="plain" :type="['CLOSED','ARCHIVED'].includes(row.status) ? 'success' : 'warning'">{{ label(row.status) }}</el-tag></div><small>{{ row.businessNo }}</small><span>{{ row.vehicle.businessNo }} · {{ row.cityName }}</span><time>{{ stamp(row.occurredAt) }}<VideoOff v-if="!row.videoCount" :size="13"/></time></button><el-empty v-if="!rows.length" description="没有符合条件的事故" :image-size="64"/><el-pagination v-model:current-page="page" :total="total" :page-size="5" layout="prev,pager,next" small @current-change="search(false)"/></aside><main class="pm-case-main"><ProvincePageState :error="detailError" :loading="detailLoading" @retry="loadDetail"><template v-if="detail"><header class="pm-case-identity"><div><h2>{{ detail.title }}<el-tag type="warning" effect="plain">{{ label(detail.status) }}</el-tag><el-button v-if="session.user?.permissions.includes('archive:vehicle:read')" link type="primary" @click="openVehicle">车辆档案 →</el-button></h2><p>{{ detail.vehicle.businessNo }} · {{ detail.cityName }} · {{ detail.address || detail.organization.name }} · {{ stamp(detail.occurredAt) }}</p></div><el-button v-if="canWrite" type="primary" plain @click="supervise">关联督办</el-button></header><div class="pm-evidence-grid"><AccidentVideoPlayer :videos="detail.videos" :cursor-time="cursor" :playing="playing" :speed="speed" :source-state="detail.videoState" @seek="cursor = Math.max(windowFrom, Math.min(windowTo, $event))" @update:playing="playing = $event"/><section class="pm-evidence-map"><header><strong>事故窗口轨迹</strong><span><i/>轨迹 <i class="incident"/>事发点</span></header><ProvinceMonitoringMap :key="`${detail.id}-${windowMinutes}`" :track="detail.track" :cursor-time="cursor" :incident="{ longitude: detail.longitude, latitude: detail.latitude }" height="300px"/><div class="pm-inline-facts"><span>速度 <b>{{ number(currentFix?.speed, ' km/h') }}</b></span><span>电量 <b>{{ number(currentFix?.battery, '%') }}</b></span><span><b>{{ currentFix ? label(currentFix.autonomousState) : '此时无定位上报' }}</b></span></div><p v-if="!detail.access.tracks" class="pm-muted">当前账号没有轨迹查询权限</p><p v-else-if="!detail.track.length" class="pm-muted">事故窗口内暂无轨迹记录</p><p v-if="detail.trackTruncated" class="pm-warning">轨迹超过5000点，请缩短证据窗口</p></section></div><div class="pm-window-switch"><strong>事发前后时间线</strong><el-radio-group v-model="windowMinutes" aria-label="事故证据窗口" @change="loadDetail"><el-radio-button v-for="minutes in [5,15,30]" :key="minutes" :value="minutes">前后{{ minutes }}分钟</el-radio-button></el-radio-group><span>视频与轨迹共用采集时间</span></div><EvidenceTimeline v-model="cursor" v-model:playing="playing" v-model:speed="speed" :from="windowFrom" :to="windowTo" :videos="detail.videos" :incident-at="incidentAt" title="证据回放" :disabled="!detail.track.length && !detail.videos.some((v: any) => v.state === 'AVAILABLE')"/><div class="pm-case-bottom"><section class="pm-detail-card"><h3>事件证据</h3><el-table :data="events" size="small" @row-click="(row: any) => cursor = Date.parse(row.occurredAt)"><el-table-column label="时间" width="90"><template #default="{ row }">{{ stamp(row.occurredAt, true) }}</template></el-table-column><el-table-column prop="kind" label="类型" width="65"/><el-table-column prop="title" label="事项" min-width="180"/></el-table><small class="pm-muted">点击事件定位到对应采集时间</small></section><section class="pm-detail-card"><h3>属地处置进展</h3><dl class="pm-facts single"><div><dt>处置机构</dt><dd>{{ detail.organization.name }}</dd></div><div><dt>当前状态</dt><dd>{{ label(detail.status) }}</dd></div><div><dt>调查情况</dt><dd>{{ detail.investigation || '尚无调查反馈' }}</dd></div><div><dt>责任认定</dt><dd>{{ detail.responsibility || '尚无认定结果' }}</dd></div><div><dt>最近进展</dt><dd>{{ detail.disposalProgress || '尚无处置反馈' }}</dd></div><div><dt>更新于</dt><dd>{{ stamp(detail.updatedAt) }}</dd></div></dl></section></div></template><div v-else-if="!detailLoading" class="pm-no-selection"><CarFront :size="36"/><strong>选择事故，核查关联证据</strong><span>事故视频、轨迹和处置资料会在这里展示</span></div></ProvincePageState></main></div></ProvincePageState></section></template>
